function sourceOfficers(){
 const out=[],seen=new Set();
 try{(HIST||[]).forEach(o=>{if(!seen.has(o.name)){seen.add(o.name);out.push(o)}})}catch(e){}
 (window.EXTRA_HISTORICAL_OFFICERS||[]).forEach(o=>{if(!seen.has(o.name)){seen.add(o.name);out.push(o)}});
 return out;
}

// Officers not found as a confirmed row on the supplied page are kept separate
// from the exact data and restrained to ordinary-officer ranges.
const FALLBACK={};
sourceOfficers().forEach(o=>{
 if(EXACT[o.name]||HINATA_NAMES.has(o.name))return;
 const keys=['lead','war','int','pol','cha'];
 const vals=keys.map(k=>Math.max(12,Math.min(100,Number(o[k])||50)));
 let best=0;for(let i=1;i<vals.length;i++)if(vals[i]>vals[best])best=i;
 const row={};
 keys.forEach((k,i)=>{
  const cap=i===best?88:82;
  row[k]=Math.max(15,Math.min(cap,Math.round(vals[i])));
 });
 FALLBACK[o.name]=row;
});
window.ROTK4_UNCONFIRMED_FALLBACK=FALLBACK;

function aptitude(o){
 if((Number(o.int)||0)>=90&&(Number(o.war)||0)<80)return '弩兵';
 if((Number(o.war)||0)>=90)return '騎兵';
 if((Number(o.war)||0)>=80)return '槍兵';
 return '剣盾兵';
}
function applyOne(o){
 if(!o||!o.name||HINATA_NAMES.has(o.name))return false;
 const e=EXACT[o.name];
 if(e){
  o.lead=e[0];o.war=e[1];o.int=e[2];o.pol=e[3];o.cha=e[4];
  o.statSource='三國志IV参照頁・直接値';
 }else if(FALLBACK[o.name]){
  Object.assign(o,FALLBACK[o.name]);
  o.statSource='参照頁未確定・補助設定';
 }else return false;
 o.apt=aptitude(o);
 if(o.type)o.type=o.apt;
 return true;
}
function applyAll(){
 try{(HIST||[]).forEach(applyOne)}catch(e){}
 (window.EXTRA_HISTORICAL_OFFICERS||[]).forEach(applyOne);
 try{
  if(typeof state!=='undefined'&&state?.officers){
   state.officers.forEach(applyOne);
   if(state.battle?.units)state.battle.units.forEach(u=>{
    if(HINATA_NAMES.has(u.name))return;
    const e=EXACT[u.name],f=FALLBACK[u.name];
    if(e){u.lead=e[0];u.war=e[1];u.int=e[2];u.type=aptitude({lead:e[0],war:e[1],int:e[2]});}
    else if(f){u.lead=f.lead;u.war=f.war;u.int=f.int;u.type=aptitude(f);}
   });
   if(state.historicalStatVersion!==118){
    state.historicalStatVersion=118;
    if(typeof log==='function')log(`三國志IV参照頁の確認済み能力値を${Object.keys(EXACT).length}名へ直接反映した。`);
   }
  }
 }catch(e){console.warn('v24.18 stats state:',e)}
}
applyAll();

const previousRender=window.render;
